95	CachedFileRcPtr LocalFileFormat::read(std::istream & istream,
96	                                      const std::string & /*fileName*/,
97	                                      Interpolation interp) const
98	{
99	    // Parse Header Info.
100	    int lut_size = -1;
101	    float from_min = 0.0;
102	    float from_max = 1.0;
103	    int version = -1;
104	    int components = -1;
105	
106	    const int MAX_LINE_SIZE = 4096;
107	    char lineBuffer[MAX_LINE_SIZE];
108	    int currentLine = 0;
109	
110	    // PARSE HEADER INFO
111	    {
112	        std::string headerLine("");
113	        do
114	        {
115	            istream.getline(lineBuffer, MAX_LINE_SIZE);
116	            ++currentLine;
117	            headerLine = std::string(lineBuffer);
118	
119	            if(StringUtils::StartsWith(headerLine, "Version"))
120	            {
121	                // " " in format means any number of spaces (white space,
122	                // new line, tab) including 0 of them.
123	                // "Version1" is valid.
124	                if (sscanf(lineBuffer, "Version %d", &version) != 1)
125	                {
126	                    ThrowErrorMessage("Invalid 'Version' Tag", currentLine, headerLine);
127	                }
128	                else if (version != 1)
129	                {
130	                    ThrowErrorMessage("Only format version 1 supported", currentLine, headerLine);
131	                }
132	            }
133	            else if(StringUtils::StartsWith(headerLine, "From"))
134	            {
135	                char fromMinS[64] = "";
136	                char fromMaxS[64] = "";
137	#ifdef _WIN32
138	                if (sscanf_s(lineBuffer, "From %63s %63s", fromMinS, 64, fromMaxS, 64) != 2)
139	#else
140	                if (sscanf(lineBuffer, "From %63s %63s", fromMinS, fromMaxS) != 2)
141	#endif
142	                {
143	                    ThrowErrorMessage("Invalid 'From' Tag", currentLine, headerLine);
144	                }
145	                else
146	                {
147	                    const auto fromMinAnswer = NumberUtils::from_chars(fromMinS, fromMinS + 64, from_min);
148	                    const auto fromMaxAnswer = NumberUtils::from_chars(fromMaxS, fromMaxS + 64, from_max);
149	
150	                    if (fromMinAnswer.ec != std::errc() || fromMaxAnswer.ec != std::errc())
151	                    {
152	                        ThrowErrorMessage("Invalid 'From' Tag", currentLine, headerLine);
153	                    }
154	                }
155	            }
156	            else if(StringUtils::StartsWith(headerLine, "Components"))
157	            {
158	                if (sscanf(lineBuffer, "Components %d", &components) != 1)
159	                {
160	                    ThrowErrorMessage("Invalid 'Components' Tag", currentLine, headerLine);
161	                }
162	            }
163	            else if(StringUtils::StartsWith(headerLine, "Length"))
164	            {
165	                if (sscanf(lineBuffer, "Length %d", &lut_size) != 1)
166	                {
167	                    ThrowErrorMessage("Invalid 'Length' Tag", currentLine, headerLine);
168	                }
169	            }
170	        }
171	        while (istream.good() && !StringUtils::StartsWith(headerLine,'{'));
172	    }
173	
174	    if (version == -1)
175	    {
176	        ThrowErrorMessage("Could not find 'Version' Tag", -1, "");
177	    }
178	    if (lut_size == -1)
179	    {
180	        ThrowErrorMessage("Could not find 'Length' Tag", -1, "");
181	    }
182	    if (lut_size < 2 || lut_size > static_cast<long>(Max1DLUTLength))
183	    {
184	        ThrowErrorMessage(
185	            ("'Length' must be between 2 and " + std::to_string(Max1DLUTLength)).c_str(),
186	            -1, "");
187	    }
188	    if (components == -1)
189	    {
190	        ThrowErrorMessage("Could not find 'Components' Tag", -1, "");
191	    }
192	    if (components < 0 || components>3)
193	    {
194	        ThrowErrorMessage("Components must be [1,2,3]", -1, "");
195	    }
196	
197	    Lut1DOpDataRcPtr lut1d = std::make_shared<Lut1DOpData>(lut_size);
198	    if (Lut1DOpData::IsValidInterpolation(interp))
199	    {
200	        lut1d->setInterpolation(interp);
201	    }
202	
203	    lut1d->setFileOutputBitDepth(BIT_DEPTH_F32);
204	    Array & lutArray = lut1d->getArray();
205	    unsigned long i = 0;
206	    {
207	        istream.getline(lineBuffer, MAX_LINE_SIZE);
208	        ++currentLine;
209	
210	        int lineCount=0;
211	
212	        std::vector<float> values;
213	
214	        while (istream.good())
215	        {
216	            const std::string line = StringUtils::Trim(std::string(lineBuffer));
217	            if (Platform::Strcasecmp(line.c_str(), "}") == 0)
218	            {
219	                break;
220	            }
221	
222	            if (line.length() != 0)
223	            {
224	                values.clear();
225	
226	                char inputLUT[4][64] = {"", "", "", ""};
227	#ifdef _WIN32
228	                if (sscanf_s(lineBuffer, "%63s %63s %63s %63s", inputLUT[0], 64,
229	                           inputLUT[1], 64, inputLUT[2], 64, inputLUT[3],
230	                           64) != components)
231	#else
232	                if (sscanf(lineBuffer, "%63s %63s %63s %63s", inputLUT[0],
233	                           inputLUT[1], inputLUT[2], inputLUT[3]) != components)
234	#endif
235	                {
236	                    std::ostringstream os;
237	                    os << "Malformed LUT line. Expecting a ";
238	                    os << components << " components entry.";
239	
240	                    ThrowErrorMessage("Malformed LUT line", currentLine, line);
241	                }
242	
243	                if (lineCount >= lut_size)
244	                {
245	                    ThrowErrorMessage("Too many entries found", currentLine, "");
246	                }
247	
248	                values.resize(components);
249	
250	                for (int i = 0; i < components; i++)
251	                {
252	                    float v = NAN;
253	                    const auto result = NumberUtils::from_chars(inputLUT[i], inputLUT[i] + 64, v);
254	
255	                    if (result.ec != std::errc())
256	                    {
257	                        std::ostringstream os;
258	                        os << "Malformed LUT line. Could not convert component";
259	                        os << i << " to a floating point number.";
260	
261	                        ThrowErrorMessage("Malformed LUT line", currentLine,
262	                                            line);
263	                    }
264	
265	                    values[i] = v;
266	                }
267	
268	                // If 1 component is specified, use x1 x1 x1.
269	                if (components == 1)
270	                {
271	                    lutArray[i]     = values[0];
272	                    lutArray[i + 1] = values[0];
273	                    lutArray[i + 2] = values[0];
274	                    i += 3;
275	                    ++lineCount;
276	                }
277	                // If 2 components are specified, use x1 x2 0.0.
278	                else if (components == 2)
279	                {
280	                    lutArray[i]     = values[0];
281	                    lutArray[i + 1] = values[1];
282	                    lutArray[i + 2] = 0.0f;
283	                    i += 3;
284	                    ++lineCount;
285	                }
286	                // If 3 component is specified, use x1 x2 x3.
287	                else if (components == 3)
288	                {
289	                    lutArray[i]     = values[0];
290	                    lutArray[i + 1] = values[1];
291	                    lutArray[i + 2] = values[2];
292	                    i += 3;
293	                    ++lineCount;
294	                }
295	
296	                // No other case, components is in [1..3].
297	            }
298	
299	            istream.getline(lineBuffer, MAX_LINE_SIZE);
300	            ++currentLine;
301	        }
302	
303	        if (lineCount != lut_size)
304	        {
305	            ThrowErrorMessage("Not enough entries found", currentLine, "");
306	        }
307	    }
308	
309	    LocalCachedFileRcPtr cachedFile = LocalCachedFileRcPtr(new LocalCachedFile());
310	    cachedFile->lut = lut1d;
311	    cachedFile->from_min = from_min;
312	    cachedFile->from_max = from_max;
313	    return cachedFile;
