316	void LocalFileFormat::bake(const Baker & baker,
317	                           const std::string & formatName,
318	                           std::ostream & ostream) const
319	{
320	
321	    const int DEFAULT_1D_SIZE = 4096;
322	
323	    if(formatName != "spi1d")
324	    {
325	        std::ostringstream os;
326	        os << "Unknown spi format name, '";
327	        os << formatName << "'.";
328	        throw Exception(os.str().c_str());
329	    }
330	
331	    //
332	    // Initialize config and data
333	    //
334	
335	    ConstConfigRcPtr config = baker.getConfig();
336	
337	    int onedSize = baker.getCubeSize();
338	    if(onedSize==-1) onedSize = DEFAULT_1D_SIZE;
339	
340	    const std::string shaperSpace = baker.getShaperSpace();
341	
342	    float fromInStart = 0.0f;
343	    float fromInEnd = 1.0f;
344	
345	    //
346	    // Generate 1DLUT
347	    //
348	
349	    std::vector<float> onedData;
350	    onedData.resize(onedSize * 3);
351	
352	    if (!shaperSpace.empty())
353	    {
354	        GetShaperRange(baker, fromInStart, fromInEnd);
355	        GenerateLinearScaleLut1D(onedData.data(), onedSize, 3, fromInStart, fromInEnd);
356	    }
357	    else
358	    {
359	        GenerateIdentityLut1D(&onedData[0], onedSize, 3);
360	    }
361	
362	    PackedImageDesc onedImg(&onedData[0], onedSize, 1, 3);
363	    ConstCPUProcessorRcPtr inputToTarget = GetInputToTargetProcessor(baker);
364	    inputToTarget->apply(onedImg);
365	
366	    //
367	    // Write LUT
368	    //
369	
370	    // Set to a fixed 6 decimal precision
371	    ostream.setf(std::ios::fixed, std::ios::floatfield);
372	    ostream.precision(6);
373	
374	    // Header
375	    ostream << "Version 1" << "\n";
376	    ostream << "From " << fromInStart << " " << fromInEnd << "\n";
377	    ostream << "Length " << onedSize << "\n";
378	    ostream << "Components 3" << "\n";
379	    ostream << "{" << "\n";
380	
381	    // Write 1D data
382	    for(int i=0; i<onedSize; ++i)
383	    {
384	        ostream << "    "
385	                << onedData[3*i+0] << " "
386	                << onedData[3*i+1] << " "
387	                << onedData[3*i+2] << "\n";
388	    }
389	
390	    // Footer
391	    ostream << "}" << "\n";
392	}
